# Guide text, part 5 (ID card maker, calendar maker, emergency numbers)
from g4 import T
G = {}
G["id-card-maker.html"] = T(
 "ID Card Maker Online Free – Employee, Student & Event Cards | DailyPdfLife",
 "Design ID cards for employees, students, events and visitors with photo, logo, QR code and signature. Front and back, standard CR80 size, print-ready PDF.",
 ("About the ID card maker", "<p>Make professional ID cards without design software. Choose Employee, Student, Event or Visitor, pick one of four designs in portrait or landscape, add the organisation logo, the person's photo and details, and the back of the card with address, emergency contact, a QR code and an authorised signature. Cards are made at the standard 85.6 × 54 mm (CR80) size at 300 dpi, so they print sharp.</p>"),
 ("How to make an ID card", "<ol><li>Choose the card type, design, shape and colour.</li><li>Type the organisation name and add the logo.</li><li>Add the photo, name, role, ID number and other details.</li><li>Fill in the back: address, emergency contact and a note. The QR code is made from the name and ID unless you type your own text or link.</li><li>Download a card-size PDF, an A4 sheet with 8 cards for printing, or PNG images.</li></ol>"),
 "Printing tips",
 "<p>Print the A4 sheet at 100% (“Actual size”) on thick card paper, 250 to 300 gsm, then cut along the grey lines and laminate. For double-sided cards, print the fronts, put the sheet back in the printer and print the backs; the backs are mirrored so they line up. Many print shops can also print PVC cards from the PNG files. Use a clear, front-facing photo; the <a href=\"passport-photo.html\">Passport photo</a> tool can make one with a plain background.</p>",
 [("What size is a standard ID card?", "85.6 × 54 mm, the same as a bank card (CR80)."),
  ("Can I make cards for many people?", "Yes: make one, download it, then change the name, photo and ID for the next. Your design is remembered."),
  ("Can I put a QR code on the card?", "Yes, it's on the back. Type a link or text, or leave it empty to use the name and ID."),
  ("Is the information uploaded?", "No, cards are made on your device.")],
 [("Passport photo", "passport-photo.html"), ("QR code", "qr-code.html"), ("Remove background", "remove-bg.html")])
G["calendar-maker.html"] = T(
 "Calendar Maker – Custom Photo Calendar 2027 with Hijri & Bangla Dates | DailyPdfLife",
 "Make a printable month or year calendar with your own photos, colours and events, Saudi, UAE or Bangladesh holidays, and Hijri or Bangla dates. English, বাংলা or العربية.",
 ("About the Calendar maker", "<p>Create a calendar that is truly yours: a single month, a 12-page wall calendar, or a whole year on one page. Add a family photo or a different photo for every month, your company logo and name, and your own dates such as birthdays and anniversaries. Each day can also show the Hijri (Umm al-Qura) or Bangla (বঙ্গাব্দ) date, and public holidays for Saudi Arabia, the UAE or Bangladesh are marked for you, including the Eids.</p>"),
 ("How to make a calendar", "<ol><li>Choose one month, 12 pages, or the year on one page, then the year and month.</li><li>Pick a design: Photo top, Minimal or Bold, the paper size and the language.</li><li>Add your photo, a title and a logo, and choose a colour.</li><li>Set the first day of the week and the weekend, the second date and the holidays.</li><li>Add your own dates, then download the PDF or a PNG of the page.</li></ol>"),
 "Good to know",
 "<p>Eid dates are worked out from the Umm al-Qura calendar and may move by a day once the moon is sighted, and Bangladesh's Eid dates can differ from Saudi Arabia's. The Bangla date follows the revised Bangladesh calendar, where Pohela Boishakh is always 14 April. For a wall calendar, ask a print shop to print the 12-page PDF on thick paper and spiral-bind it at the top. Photos print best when they are sharp and at least 2000 pixels wide.</p>",
 [("Can I use a different photo for each month?", "Yes. Go to the month and add a photo under “Different photo for this month”."),
  ("Which holidays are included?", "Saudi Arabia, UAE and Bangladesh national days and the Eids. Add any other date yourself."),
  ("Can the calendar be in Bangla or Arabic?", "Yes, month and day names and numbers follow the language you choose."),
  ("Are my photos uploaded?", "No, the calendar is made on your device.")],
 [("Hijri converter", "hijri-converter.html"), ("Photo collage", "photo-collage.html"), ("Date calculator", "date-calculator.html")])
G["emergency-numbers.html"] = T(
 "Emergency Numbers – Saudi, UAE, Bangladesh, Gulf & More | DailyPdfLife",
 "Police, ambulance, fire and helpline numbers for Saudi Arabia, the UAE, Gulf countries, Bangladesh, India, Pakistan and more, with tap-to-call and nearest hospital on the map.",
 ("About Emergency numbers", "<p>In an emergency there is no time to search. Choose your country and city to see the main emergency number in large print and every other important line: police, ambulance, fire, traffic accidents, health advice and helplines for women and children. Tap any number to call it. The page also finds the nearest hospital, police station, pharmacy or embassy on the map and can send your exact location to family on WhatsApp.</p>"),
 ("How to use it", "<ol><li>Choose your country and city. Your choice is remembered on this phone.</li><li>Tap the big red number for the main emergency service, or any other line below it.</li><li>Under <b>Find the nearest</b>, tap a place to open it on the map near you.</li><li>Tap <b>Send my location on WhatsApp</b> to share your exact position.</li></ol>"),
 "Important for Saudi Arabia",
 "<p>The unified number 911 works in the Riyadh, Makkah, Madinah and Eastern Province regions. In other regions, call 999 for police, 997 for an ambulance and 998 for civil defence; the page shows the right numbers for the city you pick. For minor road accidents with no injuries, call Najm. Add this page to your home screen so it opens even without internet, and save the main numbers in your phone's contacts.</p>",
 [("Can I call without credit or a SIM card?", "In most countries the emergency number works from any mobile, even without credit."),
  ("What is the emergency number in Bangladesh?", "999 for police, fire service and ambulance; it is free."),
  ("Which number is for ambulances in the UAE?", "998. Police is 999 and fire is 997."),
  ("Is my location shared with DailyPdfLife?", "No, it is used only on your phone to open the map or WhatsApp.")],
 [("Prayer times", "prayer-times.html"), ("Hijri converter", "hijri-converter.html"), ("Unit converter", "unit-converter.html")])
